import React from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ProgressBar, type ProgressColor } from "@sb-components/atoms/display/Progress/Progress"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * BLOCK ΓÇö `QuotaBar`: one labelled used/limit AI-credit row whose fill colour
 * steps through a 3-tier ramp (accent Γëñ75% ┬╖ warning >75% ┬╖ danger >90%) as the
 * window fills up, with an optional reset-time caption underneath.
 *
 * Two of these stack inside `QuotaLane` (a 5-hour window, a 7-day window), which
 * itself sits inside the `AiQuotaModal` overlay.
 *
 * LEAF by STRUCTURE: the fill tone, the unit suffix, and the reset caption are all
 * DATA ΓçÆ states of one leaf. The caller flipping `isSkeleton` is its own leaf, same
 * convention as `RatingBar`/`PriceTag`.
 */

/** Usage ratio above which the bar shows warning colour (>75%). */
const WARNING_USAGE_RATIO = 0.75

/** Usage ratio above which the bar shows danger colour (>90%). */
const DANGER_USAGE_RATIO = 0.9

/**
 * Map consumed share to a progress-bar colour tier. Ported verbatim (same
 * thresholds, same `limit <= 0` edge case) from
 * `src`'s `resolveQuotaBarFillTone`.
 * @param ratio - Consumed share, already clamped to `[0, 1]`.
 * @returns `"accent"` (Γëñ75%), `"warning"` (>75%), or `"danger"` (>90%).
 */
const resolveQuotaBarFillTone = (ratio: number): ProgressColor => {
    if (ratio > DANGER_USAGE_RATIO) {
        return "danger"
    }
    if (ratio > WARNING_USAGE_RATIO) {
        return "warning"
    }
    return "accent"
}

/** Props for {@link QuotaBar}. */
export interface QuotaBarProps {
    /** Window label (e.g. "Next 5 hours"). Block carries no i18n ΓÇö caller localises. */
    label: string
    /** Amount consumed in the window. */
    used: number
    /** Cap for the window (`0` means "no allowance"). */
    limit: number
    /** Unit suffix appended after the counts when {@link QuotaBarProps.showUnit} is true. */
    unit?: string
    /** `true` ΓåÆ append {@link QuotaBarProps.unit} after the used/limit counts. */
    showUnit?: boolean
    /** Reset time shown under the bar (e.g. "Resets at 18:50 01/06"). `null`/omitted hides the row. */
    resetLabel?: string | null
    /** `true` ΓåÆ the block draws its own row mirror (label, bar, caption all shimmer). */
    isSkeleton?: boolean
    /** Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * The quota usage row. See the file header for the full contract.
 * @param props - {@link QuotaBarProps}
 */
const QuotaBar = ({
    label,
    used,
    limit,
    unit,
    showUnit = false,
    resetLabel,
    isSkeleton = false,
    classNames,
}: QuotaBarProps) => {
    const ratio = limit > 0
        ? Math.min(1, Math.max(0, used / limit))
        : (used > 0 ? 1 : 0)
    const fillTone = resolveQuotaBarFillTone(ratio)
    const value = ratio * 100

    // Whether the caption row has a box to occupy: a resting bar always reserves
    // it (┬º8, see file header); a live bar only reserves it when there IS a
    // reset time to show.
    const showCaption = isSkeleton || resetLabel != null

    // LabelRow ΓÇö the window label on the left, the "used / limit" count on the
    // right. Peers on one baseline row (┬º13b), same shape as `RatingBar`'s own
    // label+key row: `StackH` with `justify="between"`, not `Cluster` ΓÇö there
    // are exactly two fixed slots here, not a repeating same-kind list.
    const labelRow = (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="center"
            justify="between"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}


                        text={label}
                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        weight="medium"
                        tabularNums
                        isSkeleton={isSkeleton}


                        text={(
                            <>
                                {used}
                                {" / "}
                                {limit}
                                {showUnit && unit ? (
                                    <>
                                        {" "}
                                        <Typography size="sm" color="muted" isInline text={unit} />
                                    </>
                                ) : null}
                            </>
                        )}
                    />
                ),
            ]}
        />
    )

    const bar = (
        <div>
            <ProgressBar
                value={value}
                max={100}
                color={fillTone}
                size="sm"
                ariaLabel={label}
                isSkeleton={isSkeleton}

            />
        </div>
    )

    return (
        <StackV identity={{ tier: "block", component: "QuotaBar" }}
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => labelRow,
                () => bar,
                ...(showCaption ? [() => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}


                        text={resetLabel ?? undefined}
                    />
                )] : []),
            ]}
        />
    )
}

export { QuotaBar }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` ΓÇö the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (┬º12b) ΓÇö the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited ΓåÆ renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) ΓÇö an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` ΓÇö this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <HeroSkeleton className="h-4 w-64 max-w-full rounded" />
    }
    // no seat cap at this phase ΓåÆ no honest scarcity reason ΓåÆ stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` ΓÇö the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ΓçÆ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `┬╖` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // ┬º5a: icon matches the FONT-SIZE of the text beside it ΓÇö `sm`
                        // (14px) ΓçÆ `size-3.5`. ┬º5.0a: below `size-5` ΓçÆ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) ΓÇö but they're still TWO SEPARATE cluster items, since the
                    // `┬╖` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}Γé½ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` ΓÇö single-component namespace ΓçÆ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

import React from "react"
import { BuildingsIcon } from "@phosphor-icons/react"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ConsultantCard` ΓÇö one recruiting consultant as a self-contained pressable
 * tile (photo, name, role, company, blurb) that opens their profile on press.
 * Built on `SurfaceCard.Pressable`. `Minimal` drops `jobTitle`/`companyTitle`/
 * `description` together; `isSkeleton` keeps the same tree as shimmer.
 */

/** One recruiting consultant ΓÇö plain data, the block builds the tile from it. */
export interface ConsultantCardConsultant {
    /** Stable id, passed back to {@link ConsultantCardProps.onOpen}. */
    id: string
    /** Full name ΓÇö the card's accessible name. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. Row disappears when absent. */
    companyTitle?: string
    /** Short bio/blurb. Row disappears when absent. */
    description?: string
    /** Photo URL. Empty/missing ΓåÆ `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
}

/** Props for {@link ConsultantCard}. */
export interface ConsultantCardProps {
    /** The consultant this tile represents. */
    consultant: ConsultantCardConsultant
    /** Fired with {@link ConsultantCardConsultant.id} when the visitor opens this consultant's profile. */
    onOpen: (id: string) => void
    /**
     * `true` ΓåÆ `Image` and every `Typography` line switch to their own shimmer,
     * and the tile stops accepting presses (there is no id to open yet). See
     * the file header for why this does NOT flow into `.Pressable`'s own flag.
     */
    isSkeleton?: boolean
}

/**
 * ONE consultant tile. See the file header for the full contract.
 *
 * @param props - {@link ConsultantCardProps}
 */
const ConsultantCard = ({
    consultant,
    onOpen,
    isSkeleton = false,
}: ConsultantCardProps) => {
    const { id, fullName, jobTitle, companyTitle, description, avatarUrl } = consultant

    const nameRow = (
        <StackV gap={1} isSkeleton={isSkeleton} items={[
            () => (
                <Typography
                    size="sm"
                    weight="medium"
                    truncate
                    isSkeleton={isSkeleton}
                    text={fullName}

                />
            ),
            ...(isSkeleton || jobTitle ? [() => (
                <Typography
                    size="xs"
                    color="muted"
                    truncate
                    isSkeleton={isSkeleton}
                    text={jobTitle}

                />
            )] : []),
        ]} />
    )

    return (
        <div>
            <div>
                <SurfaceCard
                    onPress={() => onOpen(id)}
                    isDisabled={isSkeleton}

                    body={() => (
                        <StackV
                            gap={4}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div>
                                        <Image
                                            src={avatarUrl}
                                            alt={fullName}
                                            ratio="square"
                                            radius="lg"
                                            isSkeleton={isSkeleton}

                                        />
                                    </div>
                                ),
                                () => nameRow,
                                ...(isSkeleton || companyTitle
                                    ? [
                                        () => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                truncate
                                                prefixIcon={BuildingsIcon}
                                                isSkeleton={isSkeleton}
                                                text={companyTitle}

                                            />
                                        ),
                                    ]
                                    : []),
                                ...(isSkeleton || description
                                    ? [
                                        () => (
                                            <Typography
                                                size="sm"
                                                color="muted"
                                                lineClamp={2}
                                                isSkeleton={isSkeleton}
                                                text={description}

                                            />
                                        ),
                                    ]
                                    : []),
                            ]}
                        />
                    )}
                />
            </div>
        </div>
    )
}

export { ConsultantCard }

import React from "react"
import { AsyncContent, type AsyncContentEmptyProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ConsultantCard, type ConsultantCardConsultant } from "@sb-components/starci/blocks/consultant/ConsultantCard/ConsultantCard"

/**
 * `ConsultantDirectoryGrid` ΓÇö the consultant directory's browse surface: a
 * match count above the cards, across the loading ΓåÆ empty ΓåÆ content lifecycle.
 * `AsyncContent` owns the branch switch, `Grid` the responsive track,
 * `ConsultantCard` one tile. The count line renders inside the `content` branch
 * only, beside real cards.
 */

/** Props for {@link ConsultantDirectoryGrid}. */
export interface ConsultantDirectoryGridProps {
    /**
     * The current page's consultants, already sorted by the caller. `undefined`
     * ΓçÆ the list has not resolved yet (see {@link ConsultantDirectoryGridProps.isLoading}).
     */
    consultants?: Array<ConsultantCardConsultant>
    /**
     * How many consultants the directory lists in total. `undefined` ΓçÆ the
     * count line does not render yet (see file header's judgement call).
     */
    count?: number
    /**
     * `true` while the consultant list's own fetch has not resolved. Passed
     * straight to `AsyncContent` ΓÇö this block never infers it from
     * `consultants` itself (see file header).
     */
    isLoading: boolean
    /** Fired with a consultant's id when their card is pressed. */
    onOpenConsultant: (id: string) => void
    /** The empty-state message, already localized by the caller (see file header for why this stays a caller prop). */
    emptyTitle: string
    /** Accessible name for the directory region ΓÇö the block has no visible heading of its own. */
    ariaLabel: string
}

/** How many placeholder tiles mirror the grid while the list hasn't resolved ΓÇö ported from the real `ConsultantGrid`'s `SKELETON_COUNT`. */
const SKELETON_TILE_COUNT = 6

/** Skeleton tiles pass this as `onOpen` ΓÇö `ConsultantCard.isSkeleton` disables its own press, so it never fires. */
const NOOP = () => {}

/** The block's own wording for the count line (┬º14d.1) ΓÇö the caller only ever hands over a bare number. */
const countLabel = (count: number): string => `${count} consultants`

/**
 * The consultant directory's browse surface. See the file header for the full
 * contract and why the count line only shows beside real cards.
 *
 * @param props - {@link ConsultantDirectoryGridProps}
 */
const ConsultantDirectoryGrid = ({
    consultants,
    count,
    isLoading,
    onOpenConsultant,
    emptyTitle,
    ariaLabel,
}: ConsultantDirectoryGridProps) => {
    // Resolved-but-zero, matching the real `ConsultantGrid`'s Redux-driven gating
    // (`!consultants` = loading, `sortedConsultants.length === 0` = empty).
    const isEmpty = !isLoading && (consultants?.length ?? 0) === 0

    const skeletonTiles: Array<GridItem> = Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <ConsultantCard
                consultant={{ id: `skeleton-${index}`, fullName: "" }}
                onOpen={NOOP}
                isSkeleton


            />
        ),
    }))

    const tiles: Array<GridItem> = (consultants ?? []).map((consultant) => ({
        key: consultant.id,
        content: () => (
            <ConsultantCard
                consultant={consultant}
                onOpen={onOpenConsultant}


            />
        ),
    }))

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyTitle,

    }

    return (
        <div role="region" aria-label={ariaLabel}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <div>
                        <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={skeletonTiles}  />
                    </div>
                )}
                isEmpty={isEmpty}
                emptyContent={emptyContent}

                content={() => (
                    <StackV gap={4} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            ...(count !== undefined ? [() => (
                                <Typography size="sm" color="muted" text={countLabel(count)} />
                            )] : []),
                            () => (
                                <div>
                                    <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={tiles}  />
                                </div>
                            ),
                        ]} />
                )}
            />
        </div>
    )
}

export { ConsultantDirectoryGrid }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardPressableGroup, type SurfaceCardPressableGroupItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentPager` ΓÇö step to the neighbouring lesson at the foot of the reading
 * screen. It owns the "previous lesson" / "next lesson" labels and the lesson
 * title + link on each card. The right card mirrors the left so the pair reads
 * as a direction, pinning to a second column only where the grid has two (a
 * container query). Losing either card, and `isSkeleton`, are each their own
 * leaf; having no neighbour renders nothing.
 */

/** One neighbouring lesson ΓÇö plain data, the block builds the card from it. */
export interface ContentPagerNeighbour {
    /** Lesson title, shown under the direction label and clamped to two lines. */
    title: string
    /** Where the card navigates. */
    href: string
}

/** Props for {@link ContentPager}. */
export interface ContentPagerProps {
    /** The lesson before this one. Omitted ΓåÆ the left card is not drawn. */
    previous?: ContentPagerNeighbour
    /** The lesson after this one. Omitted ΓåÆ the right card is not drawn. */
    next?: ContentPagerNeighbour
    /**
     * Accessible name for the pair, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears two loose links with nothing tying
     * them together.
     */
    ariaLabel: string
    /**
     * `true` ΓåÆ the group draws its own mirror. The flag FLOWS DOWN into
     * `SurfaceCardPressableGroup`, which owns the card box and the grid, so the
     * shimmer keeps the exact shape the real cards will take (┬º12c).
     */
    isSkeleton?: boolean
}

/**
 * Previous/next lesson pager. See the file header for the full contract.
 *
 * @param props - {@link ContentPagerProps}
 */
const ContentPager = ({
    previous,
    next,
    ariaLabel,
    isSkeleton = false,
}: ContentPagerProps) => {
    // Nothing to step to in either direction ΓçÆ draw nothing at all. Reached on the
    // first and last lesson of a course, which are ordinary, not exceptional.
    if (!isSkeleton && !previous && !next) {
        return null
    }

    const items: Array<SurfaceCardPressableGroupItem> = []
    if (previous) {
        const previousCard = (
            <StackH
                gap={4}
                principle="content-row"
                align="center"
                isSkeleton={isSkeleton}
                items={[
                    // DIV position: this card is a control with its own FIXED padding
                    // (`SurfaceCardPressableGroup` tile, `cozy` inset) ΓÇö not hug-content ΓÇö
                    // so size tracks line-height, not font-size. Title is `text-sm` ΓçÆ `size-5`,
                    // matching the sibling `ITEM_ICON_CLS` convention this same file's parent
                    // (`SurfaceCard.tsx`) already forces for icons in this exact tile shape.
                    // Weight omitted ΓåÆ Phosphor default `regular`, correct at `size-5`.
                    () => <CaretLeftIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />,
                    ({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            gap={1}
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Typography size="xs" color="muted" text="Previous content" />,
                                () => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        lineClamp={2}
                                        underlineOnGroupHover
                                        text={previous.title}
                                    />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        )
        items.push({
            key: "previous",
            href: previous.href,
            content: () => previousCard,
        })
    }
    if (next) {
        const nextCard = (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                justify="end"
                isSkeleton={isSkeleton}
                items={[
                    ({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            gap={1}
                            principle="name-handle"
                            explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                            align="end"
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <Typography size="xs" color="muted" align="end" text="Next content" />
                                ),
                                () => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        align="end"
                                        lineClamp={2}
                                        underlineOnGroupHover
                                        text={next.title}
                                    />
                                ),
                            ]}
                        />
                    ),
                    // Same DIV position/size reasoning as the mirrored left caret above.
                    () => <CaretRightIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />,
                ]}
            />
        )
        items.push({
            key: "next",
            href: next.href,
            // Full-width lone pager card: Grid's only placement lever is `span`
            // (`GridItem.span`, capped at 2). Column-start escapes are intentionally
            // unavailable ΓÇö same contract as `PagerFullWidth` in SurfaceCardPressableGroup stories.
            span: 2,
            content: () => nextCard,
        })
    }

    return (
        <div>
            <div>
                <SurfaceCardPressableGroup ariaLabel={ariaLabel} columns={{ base: 1, sm: 2 }} items={items} isSkeleton={isSkeleton} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." />
            </div>
