import React from "react"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * `CourseBrief` ΓÇö the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `┬╖`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler ΓåÆ crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA ΓÇö the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     *  NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules ┬╖ ~14h ┬╖ 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator ΓÇö
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `┬╖`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) ΓÇö the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners ΓÇö the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` ΓåÆ the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data ΓÇö the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (┬º12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS ΓÇö units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (┬º14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={
                    breadcrumbItems?.length
                        ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <div className="w-fit">
                                {/* collapse: below @app-sm or trail ΓëÑ 4 crumbs ΓåÆ back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                                <Breadcrumbs
                                    collapseOnMobile
                                    collapseFrom={4}
                                    items={breadcrumbItems ?? []}
                                    isSkeleton={skeleton}
                                />
                            </div>
                        )
                        : undefined
                }
                title={title}
                description={description}
                meta={
                    metaParts.length > 0
                        ? () => (
                            <span>
                                <Typography size="xs" color="muted" text={metaParts.join(" ┬╖ ")} />
                            </span>
                        )
                        : undefined
                }
            />
        </div>
    )
}

/** `CourseBrief.*` ΓÇö single-component namespace ΓçÆ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import React from "react"
import { Toolbar } from "@sb-components/composites/navigation/Toolbar/Toolbar"
import { InputSearch } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `CourseQaToolbar` ΓÇö the control strip above a course Q&A question list:
 * status/scope filter tabs, a search field, and a live match count. Two stacked
 * rows ΓÇö the filter tabs go through `Toolbar` (leftTabs only), while the search
 * field + count are hand-composed in a `StackH` beside them. One leaf: active
 * filter, search text, and count loading are all data on the same two-row shape.
 */

/** Status/scope filter for the course-wide Q&A roll-up. Mirrors `src`'s `CourseQuestionFilter`. */
export type CourseQaFilter = "unanswered" | "answered" | "engagement" | "mine" | "all"

/** Filter tabs in display order ΓÇö the block's own vocabulary (┬º14d.1). */
const FILTER_ORDER: ReadonlyArray<CourseQaFilter> = ["unanswered", "answered", "engagement", "mine", "all"]

/** Filter ΓåÆ tab label, ported verbatim from `vi.json`'s `courseQa.filter.*`. */
const FILTER_LABEL: Record<CourseQaFilter, string> = {
    unanswered: "Unanswered",
    answered: "Answered",
    engagement: "Most active",
    mine: "Mine",
    all: "All",
}

/** The board's own count wording ΓÇö the caller hands over a bare number, never a formatted string. */
const resultCountLabel = (count: number): string => `${count} questions`

/** Props for {@link CourseQaToolbar}. */
export interface CourseQaToolbarProps {
    /** Which status/scope filter is active. */
    filter: CourseQaFilter
    /** Fired with the filter the reader picked. */
    onFilterChange: (filter: CourseQaFilter) => void
    /** Current text in the search field (controlled; the screen owns debouncing). */
    searchValue: string
    /** Fired with the new query on every keystroke. */
    onSearchChange: (value: string) => void
    /** How many questions the active filter + search matched. */
    resultCount: number
    /** Accessible name for the filter tab row, localized by the caller (blocks carry no i18n). */
    filterAriaLabel: string
    /**
     * `true` ΓåÆ the result count shimmers instead of printing a number. Scoped to
     * the count only ΓÇö see the file header for why the tabs and search field
     * never skeletonise.
     */
    isSkeleton?: boolean
}

/**
 * The Q&A board's control strip. See the file header for why the two rows
 * cannot collapse into one `Toolbar` call and why only the count skeletonises.
 *
 * @param props - {@link CourseQaToolbarProps}
 */
const CourseQaToolbar = ({
    filter,
    onFilterChange,
    searchValue,
    onSearchChange,
    resultCount,
    filterAriaLabel,
    isSkeleton = false,
}: CourseQaToolbarProps) => {
    const items = FILTER_ORDER.map((value) => ({
        key: value,
        label: FILTER_LABEL[value],
    }))

    return (
        <div>
            <StackV
                gap={4}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div>
                            <Toolbar
                                leftTabs={{
                                    items,
                                    selectedKey: filter,
                                    ariaLabel: filterAriaLabel,
                                    onSelectionChange: (key) => onFilterChange(String(key) as CourseQaFilter),
                                }}

                            />
                        </div>
                    ),
                    () => (
                        <StackH
                            gap={3}
                            principle="flex-action"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            justify="between"
                            at="sm"
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div className="min-w-0 flex-1 @app-sm:max-w-sm">
                                        <InputSearch
                                            value={searchValue}
                                            onValueChange={onSearchChange}
                                            placeholder="Search questions..."
                                            ariaLabel="Search questions"

                                        />
                                    </div>
                                ),
                                () => (
                                    isSkeleton ? (
                                        <Typography
                                            size="sm"
                                            color="muted"
                                            isSkeleton


                                        />
                                    ) : (
                                        <Typography
                                            size="sm"
                                            color="muted"
                                            tabularNums
                                            text={resultCountLabel(resultCount)}


                                        />
                                    )
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

