import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { FlowArrowIcon, PlayIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { InputText } from "@sb-components/atoms/forms"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `MockInterviewSetup` ΓÇö the green-room card: who is interviewing, what to call
 * this run, how hard it should be, and the button(s) that start it. Sibling of
 * `QuizSetup` (same resumable-banner-leads-the-form shape). Two start buttons are
 * two different interviews ΓÇö Q&A always exists; Design shows only when the caller
 * sets `isDesignAvailable`. The persona row is built from `Avatar` + `Typography`
 * (the second line is a role, not a handle). The "Customize" deep-config body is a
 * separate, deferred leaf.
 */

/** How hard the interviewer's questions run. The block owns the label (┬º14d.1). */
export type MockInterviewTier = "junior" | "mid" | "senior"

const TIER_LABEL: Record<MockInterviewTier, string> = {
    junior: "Junior",
    mid: "Mid-level",
    senior: "Senior",
}

/** Which start action is in flight, so the busy affordance lands on the right button. */
export type MockInterviewStartMode = "qna" | "design"

/** The interviewer greeting the candidate. */
export interface MockInterviewPersona {
    /** Interviewer's display name. */
    name: string
    /** Role line under the name, e.g. "Senior Backend @ a digital bank" ΓÇö NOT a handle. */
    role: string
    /** Uploaded avatar URL. Absent ΓåÆ `Avatar`'s own generated/initials fallback. */
    avatarSrc?: string
}

/** A run the candidate left unfinished. */
export interface MockInterviewResumable {
    /** What the run was called when it was started. */
    name: string
    /** Where the run left off, already worded by the caller ΓÇö e.g. "Left off at question 3". */
    progressLabel: string
    /** Fired when the candidate picks the run back up. */
    onResume: () => void
}

/** Props for {@link MockInterviewSetup}. */
export interface MockInterviewSetupProps {
    /** Section label, localized by the caller ΓÇö e.g. "Prepare for the interview". */
    label: string
    /** The interviewer greeting the candidate. */
    persona: MockInterviewPersona
    /** Current run name. */
    sessionName: string
    /** Fired as the candidate types a name. */
    onSessionNameChange: (value: string) => void
    /** Chosen difficulty. */
    tier: MockInterviewTier
    /** Fired when the candidate picks a tier. */
    onTierChange: (tier: MockInterviewTier) => void
    /**
     * `true` ΓåÆ this is a System-Design course, so the Design-mode start button
     * renders beside the Q&A one. The CALLER decides this (course kind lives on
     * the screen); the block never infers it.
     */
    isDesignAvailable: boolean
    /** Fired when the candidate starts the Q&A round. Always available. */
    onStartQna: () => void
    /** Fired when the candidate starts the Design round. Required once `isDesignAvailable` is set. */
    onStartDesign?: () => void
    /** A run left unfinished. Present ΓåÆ the resume banner leads the card. */
    resumable?: MockInterviewResumable
    /** Which start action is currently in flight ΓÇö drives which button shows its own spinner. */
    startingMode?: MockInterviewStartMode
    /** `true` ΓåÆ a start is in flight; both start buttons lock while one of them runs. */
    isPending?: boolean
    /** Set ΓåÆ the last start attempt failed. Reported beside the action row that failed. */
    errorMessage?: string
    /** `true` ΓåÆ the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The interview green-room card. See the file header for the full contract.
 *
 * @param props - {@link MockInterviewSetupProps}
 */
const MockInterviewSetup = ({
    label,
    persona,
    sessionName,
    onSessionNameChange,
    tier,
    onTierChange,
    isDesignAvailable,
    onStartQna,
    onStartDesign,
    resumable,
    startingMode,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: MockInterviewSetupProps) => {
    const showDesignStart = isDesignAvailable && onStartDesign != null

    // A candidate who left mid-interview almost always means to come back.
    // Making them scroll past a start button to find their own session is
    // how a run gets abandoned twice ΓÇö same reasoning as `QuizSetup`.
    const resumeBanner = resumable != null ? (
        <Callout
            title={resumable.name}
            description={resumable.progressLabel}
            actionLabel="Continue"
            onAction={resumable.onResume}

        />
    ) : null

    // Interviewer identity ΓÇö built from Avatar + Typography directly (not
    // `UserCell`): the second line is a ROLE, not an `@handle`.
    const identityRow = (
        <StackH
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <div>
                        <Avatar
                            name={persona.name}
                            src={persona.avatarSrc}
                            seed={persona.name}
                            size="md"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={1}
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    isSkeleton={isSkeleton}
                                    text={persona.name}

                                />
                            ),
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    isSkeleton={isSkeleton}
                                    text={persona.role}

                                />
                            ),
                        ]}
                    />
                ),
            ]}
        />
    )

    const sessionNameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" weight="medium" text="Session name" />,
                () => (
                    <InputText
                        value={sessionName}
                        onValueChange={onSessionNameChange}
                        placeholder="e.g. Round 1 - Backend"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const tierField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" weight="medium" text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Interview level"
                        value={tier}
                        onChange={onTierChange}

                        items={(Object.keys(TIER_LABEL) as Array<MockInterviewTier>).map((key) => ({
                            value: key,
                            content: TIER_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const actionsRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ...(showDesignStart ? [({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        label="Start Design"
                        variant="secondary"
                        prefixIcon={FlowArrowIcon}
                        onPress={onStartDesign}
                        isPending={isPending && startingMode === "design"}
                        isDisabled={isPending && startingMode !== "design"}

                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        label="Start Q&A"
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStartQna}
                        isPending={isPending && startingMode === "qna"}
                        isDisabled={isPending && startingMode !== "qna"}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action row that failed. At the top of the
    // card it would read as a problem with the whole form.
    const footer = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => actionsRow,
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            ...(resumeBanner != null ? [() => resumeBanner] : []),
                            () => identityRow,
                            () => sessionNameField,
                            () => tierField,
                            () => footer,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { MockInterviewSetup }

import React from "react"
import { CircleIcon } from "@phosphor-icons/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { ContinueCardHero } from "@sb-components/starci/blocks/learn/ContinueCard/ContinueCard"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `PersonalProjectGatePreview` ΓÇö the capstone teaser dropped into `EnrollGate`'s
 * `preview` slot inside `LearnShell`: what a trial viewer sees of the
 * personal-project workspace, behind the gate's fade/lock. Composes
 * `ContinueCardHero` for the headline, a standalone `ProgressMeter` for capstone
 * completion, and `SurfaceCard` with a `label`. Non-interactive ΓÇö the fade/lock
 * affordance belongs to `EnrollGate`. Task count and names are data on one shape.
 */

/** One milestone-0 task title shown in the teaser's task list. */
export interface PersonalProjectGatePreviewTask {
    /** Task title. */
    title: string
}

/**
 * Capstone overall completion fed to the standalone `ProgressMeter` (see file
 * header for why this stays a separate meter from `ContinueCardHero`'s own bar).
 */
export interface ProgressMeterData {
    /** Current progress value. Should fall within `[0, max]`. */
    value: number
    /** The 100% mark. Defaults to `100` (`ProgressMeter`'s own default). */
    max?: number
    /** Label rendered above the bar, e.g. "Personal project progress". */
    label?: string
}

/** Section label the block owns itself ΓÇö see file header. */
const TASK_LABEL = "Milestone 0 Tasks"

/** Props for {@link PersonalProjectGatePreview}. */
export interface PersonalProjectGatePreviewProps {
    /** Capstone project name/headline ΓÇö becomes `ContinueCardHero`'s title. */
    heroTitle: string
    /** One-line pitch under the headline ΓÇö becomes `ContinueCardHero`'s subtitle. */
    heroSubtitle: string
    /** The capstone's overall completion, shown in its own `ProgressMeter`. */
    progress: ProgressMeterData
    /** Milestone-0 task titles, in display order. */
    items: Array<PersonalProjectGatePreviewTask>
    /**
     * `true` ΓåÆ every composed leaf draws its own shimmer mirror instead of the
     * real content. Flows straight into `ContinueCardHero`, `SurfaceCard`, and
     * each task row's `Typography` (┬º12c) ΓÇö no parallel skeleton tree built here.
     */
