/**
 * The capstone teaser dropped behind `EnrollGate`'s fade. See the file header
 * for the full contract.
 *
 * @param props - {@link PersonalProjectGatePreviewProps}
 */
const PersonalProjectGatePreview = ({
    heroTitle,
    heroSubtitle,
    progress,
    items,
    isSkeleton = false,
    classNames,
}: PersonalProjectGatePreviewProps) => {
    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return ΓÇö a small named helper instead, in the style this file already uses.
    const renderTaskRow = (item: PersonalProjectGatePreviewTask, index: number) => (
        <StackH
            key={index}
            gap={2}
            principle="icon-text"
            explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"
            isSkeleton={isSkeleton}

            items={[
                () => <CircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />,
                () => (
                    <Typography
                        size="sm"
                        truncate
                        isSkeleton={isSkeleton}
                        text={item.title}

                    />
                ),
            ]}
        />
    )

    const taskList = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={items.map((item, index) => () => renderTaskRow(item, index))}
        />
    )

    return (
        <StackV identity={{ tier: "block", component: "PersonalProjectGatePreview" }}
            gap={6}
            classNames={classNames}
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <ContinueCardHero
                        title={heroTitle}
                        subtitle={heroSubtitle}
                        isSkeleton={isSkeleton}


                    />
                ),
                () => (
                    <ProgressMeter
                        value={progress.value}
                        max={progress.max}
                        label={progress.label}
                        showValue


                    />
                ),
                () => (
                    <SurfaceCard
                        label={TASK_LABEL}
                        isSkeleton={isSkeleton}


                        body={() => taskList}
                    />
                ),
            ]}
        />
    )
}

export { PersonalProjectGatePreview }

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { Alert } from "@sb-components/atoms/feedback/Alert/Alert"
import { Button } from "@sb-components/atoms/buttons/Button/Button"

/**
 * `TrialEnrollBanner` ΓÇö the ambient "you're on a trial" nudge, reused across every
 * free surface a trial learner can reach (foundations resource page and grid, and
 * leaderboard). A caller-resolved `isVisible` drives shown vs hidden; it renders
 * both a title and a description, and `isSkeleton` covers the enrollment check still
 * being in flight. Three leaves: "shown"/"hidden" differ in structure (a node vs an
 * empty tree), and the skeleton (two text bars, no CTA) is a third structure.
 */

/** Props for {@link TrialEnrollBanner}. */
export interface TrialEnrollBannerProps {
    /**
     * `true` ΓåÆ the caller has resolved the learner as a known trial learner
     * (not yet enrolled) and wants the nudge shown. `false` covers BOTH
     * "enrolled" and "not yet known" ΓÇö either way the banner renders nothing
     * (the "not yet known" window instead goes through {@link isSkeleton}).
     */
    isVisible: boolean
    /** Fired when the learner taps the CTA (caller owns opening the enroll flow). */
    onEnroll: () => void
    /**
     * `true` ΓåÆ the enrollment check that feeds `isVisible` is still in flight.
     * Reserves the banner's shape without shimmering the copy (fixed, not
     * fetched) and without a CTA (nothing to press before the check lands).
     * Wins over `isVisible`.
     */
    isSkeleton?: boolean
}

/**
 * The trial ΓåÆ enroll ambient nudge. See the file header for the self-gating
 * condition, the consolidation history, and why `isSkeleton` is a separate
 * window from `isVisible = false`.
 *
 * @param props - {@link TrialEnrollBannerProps}
 */
const TrialEnrollBanner = ({
    isVisible,
    onEnroll,
    isSkeleton = false,
}: TrialEnrollBannerProps) => {
    if (isSkeleton) {
        // `Callout` has no `isSkeleton` of its own (┬º12c gap, same one
        // `CourseTeamGate` already documents) ΓÇö its `title`/`description` slots
        // render inside `<p>` (`Alert.Title`/`Alert.Description`), which cannot
        // legally contain the `<div>` a hand-built `Typography isSkeleton` bar
        // emits (real hydration error, caught live in this exact leaf). `Alert`
        // itself DOES own `isSkeleton` and draws two safe `<div>` bars straight
        // inside its content region ΓÇö call it directly, same precedent as
        // `CourseTeamGate.tsx`.
        return (
            <div>
                <Alert
                    isSkeleton
                    status="accent"

                />
            </div>
        )
    }

    // SELF-HIDE ΓÇö the block owns its own show condition; the screen doesn't need to ask.
    if (!isVisible) {
        return null
    }

    return (
        <div>
            <Callout
                status="accent"
                title="You're on a trial"
                description="Unlock the full course and build proof of work employers can see on your profile."

                body={() => (
                    <Button
                        label="Unlock the course"
                        variant="primary"
                        size="sm"
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onEnroll}

                    />
                )}
            />
        </div>
    )
}

export { TrialEnrollBanner }

import { useState } from "react"
import { MicrophoneIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { InputTextarea } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `VoiceHero` ΓÇö the voice-first answer composer. A large push-to-talk mic with
 * its live transcript is the hero; a quiet typed textarea is the fallback for
 * browsers without speech-to-text, or lessons that only want typed answers.
 * Two structural leaves ΓÇö `MicHero` (circular button + transcript) and
 * `TypedFallback` (textarea + switch-back link) ΓÇö chosen from `sttSupported`
 * and `answerMode`, plus an ephemeral toggle reachable only when both input
 * methods are offered (`answerMode="both"` with STT supported). The
 * "type instead" / "use voice" link is a state inside each leaf, tracking the
 * `canToggle` boolean. No `isSkeleton` ΓÇö nothing to mirror.
 */

/** How the caller wants an answer collected. */
export type VoiceAnswerMode = "voice" | "text" | "both"

/** Wording for both leaves ΓÇö the block carries no i18n of its own (┬º14d.1). */
export interface VoiceHeroLabels {
    /** Aria label for the mic button while NOT listening. */
    pushToTalk: string
    /** Aria label for the mic button, and its transcript-line hint, WHILE listening with nothing recognized yet. */
    listening: string
    /** Switch-away link shown in `MicHero` when both input methods are offered. */
    typeInstead: string
    /** Switch-back link shown in `TypedFallback` when both input methods are offered. */
    useVoice: string
    /** Placeholder of the typed field, and `MicHero`'s idle empty-transcript hint. */
    placeholder: string
}

/** Props for {@link VoiceHero}. */
export interface VoiceHeroProps {
    /** `false` ΓåÆ this browser/device cannot do speech-to-text; only `TypedFallback` is ever offered. */
    sttSupported: boolean
    /** `true` ΓåÆ the mic is actively recording. */
    listening: boolean
    /** Live, not-yet-committed transcript while `listening`. Empty once recognized speech lands in `value`. */
    interimTranscript: string
    /** The committed answer ΓÇö final voice transcript, or whatever the learner typed. */
    value: string
    /** Fired as the typed field changes. Voice never calls this directly; recognized speech lands in `value` upstream. */
    onValueChange: (value: string) => void
    /** Fired when the mic button is pressed, toggling `listening`. */
    onToggleListen: () => void
    /** Which input method(s) this answer accepts. See the file header for how it decides a leaf. */
    answerMode: VoiceAnswerMode
    /** Wording for both leaves. */
    labels: VoiceHeroLabels
}

/**
 * The voice-first answer composer. See the file header for leaf selection and
 * the transcript/mic-color judgement calls.
 *
 * @param props - {@link VoiceHeroProps}
 */
const VoiceHero = ({
    sttSupported,
    listening,
    interimTranscript,
    value,
    onValueChange,
    onToggleListen,
    answerMode,
    labels,
}: VoiceHeroProps) => {
    // Ephemeral UI-only choice ΓÇö see file header. Only reachable when BOTH leaves
    // are actually on offer, so there is nothing to reset when the caller's props change.
    const [manualTyped, setManualTyped] = useState(false)

    const forcedText = !sttSupported || answerMode === "text"
    const forcedVoice = sttSupported && answerMode === "voice"
    const canToggle = !forcedText && !forcedVoice
    const showTypedFallback = forcedText || (canToggle && manualTyped)

    if (showTypedFallback) {
        return (
            <div>
                <StackV
                    gap={4}

                    items={[
                        () => (
                            <InputTextarea
                                value={value}
                                onValueChange={onValueChange}
                                placeholder={labels.placeholder}
                                ariaLabel={labels.placeholder}
                                rows={5}

                            />
                        ),
                        ...(canToggle ? [() => (
                            <Typography
                                size="sm"
                                isLink
                                text={labels.useVoice}
                                onPress={() => setManualTyped(false)}

                            />
                        )] : []),
                    ]}
                />
            </div>
        )
    }

    // Provisional whenever there is nothing FINAL to show yet: an interim fragment
    // still being recognized, or (while listening) no speech landed in `value` at all.
    const transcriptIsProvisional = listening && (interimTranscript.length > 0 || value.length === 0)
    const transcriptText = listening && interimTranscript
        ? interimTranscript
        : value || (listening ? labels.listening : labels.placeholder)

    return (
        <div>
            <StackV
                gap={4}
                principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                align="center"

                items={[
                    () => (
                        <Button
                            isIconOnly
                            size="lg"
                            variant={listening ? "danger" : "primary"}
                            prefixIcon={MicrophoneIcon}
                            ariaLabel={listening ? labels.listening : labels.pushToTalk}
                            onPress={onToggleListen}

                        />
                    ),
                    // real `src` (`VoiceHero/index.tsx:136`): `<Typography color="default">`
                    // declares NO `type` ΓçÆ defaults to base (16px), not `lg`.
                    () => (
                        <Typography
                            size="base"
                            align="center"
                            color={transcriptIsProvisional ? "muted" : "default"}
                            isItalic={transcriptIsProvisional}
                            text={transcriptText}

                        />
                    ),
                    ...(canToggle ? [() => (
                        <Typography
                            size="sm"
                            isLink
                            text={labels.typeInstead}
                            onPress={() => setManualTyped(true)}

                        />
                    )] : []),
                ]}
            />
        </div>
    )
}

export { VoiceHero }

import React from "react"
import { cn } from "@heroui/react"
import {
    BookmarkSimpleIcon,
    ChartBarIcon,
    CreditCardIcon,
    DesktopIcon,
    GraduationCapIcon,
    PaintBrushIcon,
    PencilSimpleIcon,
    ShieldCheckIcon,
    SlidersHorizontalIcon,
    StarIcon,
    WalletIcon,
} from "@phosphor-icons/react"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { Typography, type TypographyIcon } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { CollapsibleSidebar } from "@sb-components/starci/blocks/navigation/CollapsibleSidebar/CollapsibleSidebar"
import { DesktopNavRow } from "./DesktopNavRow"

/**
 * `SettingsSidebarNav` ΓÇö the account-settings destination list, drawn as a
 * collapsible desktop rail and, below `@app-md`, a sticky horizontal pill bar.
 * Two structural leaves ΓÇö `DesktopRail` (collapsible `Link`-shaped rows with a
 * divider between groups) and `MobilePillBar` (a flattened rounded-full chip
 * row). Both render the same component; only the container width differs, so
 * each story shows the branch its own `@app-md` query resolves to. `activeHref`
 * is data, so within each leaf it is a state.
 */

/** Every account-settings destination this rail can offer ΓÇö the closed vocabulary the block owns. */
export type SettingsDestinationKey =
    | "editProfile"
    | "appearance"
    | "security"
    | "sessions"
    | "courseHistory"
    | "aiSettings"
    | "aiSubscription"
    | "aiUsage"
    | "bookmarks"
    | "membership"
    | "installments"

/** One settings destination ΓÇö TYPED DOMAIN DATA only: which one, and where it navigates. */
export interface SettingsNavItem {
    /** Which destination this row is ΓÇö drives its icon + label (block-owned table below). */
    key: SettingsDestinationKey
    /** Absolute href the row navigates to. */
    href: string
}

/**
 * A cluster of destinations rendered together. No `label` field: every real group is
 * unlabelled (see `src`'s `getSettingsGroups` ΓÇö only a divider separates them), so adding
 * an unused caption prop would be inventing a case no screen asks for (┬º14d.3).
 */
export interface SettingsNavGroup {
    /** Stable React key for the group ΓÇö not shown, only used for reconciliation + the divider count. */
    key: string
    /** The destinations in this group, in display order. */
    items: Array<SettingsNavItem>
}

/** Destination ΓåÆ label. The block's own wording (┬º14d.1), never handed in by the caller. */
export const DESTINATION_LABEL: Record<SettingsDestinationKey, string> = {
    editProfile: "Edit profile",
    appearance: "Appearance",
    security: "Security",
    sessions: "Login sessions",
    courseHistory: "Learning history",
    aiSettings: "AI settings",
    aiSubscription: "AI plan",
    aiUsage: "AI usage",
    bookmarks: "Saved",
    membership: "Membership plan",
    installments: "Installments",
}

/** Destination ΓåÆ icon. Same glyphs `src`'s `nav.tsx` maps, so porting this table reads as ONE control. */
export const DESTINATION_ICON: Record<SettingsDestinationKey, TypographyIcon> = {
    editProfile: PencilSimpleIcon,
    appearance: PaintBrushIcon,
    security: ShieldCheckIcon,
    sessions: DesktopIcon,
    courseHistory: GraduationCapIcon,
    aiSettings: SlidersHorizontalIcon,
    aiSubscription: CreditCardIcon,
    aiUsage: ChartBarIcon,
    bookmarks: BookmarkSimpleIcon,
    membership: StarIcon,
    installments: WalletIcon,
}

/** Props for {@link SettingsSidebarNav}. */
export interface SettingsSidebarNavProps {
    /** Grouped destinations, in display order. */
    groups: Array<SettingsNavGroup>
    /** Which destination's `href` is being viewed right now. */
    activeHref: string
    /** Fired with a destination's `href` when its row/pill is pressed. */
    onNavigate: (href: string) => void
    /** Heading shown atop the desktop rail (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /** `localStorage` key the collapsed flag persists under, so the choice survives navigation. */
    storageKey: string
    /** Accessible name for the mobile pill nav landmark. Defaults to {@link title}. */
    mobileNavAriaLabel?: string
}

/**
 * The settings destination rail. See the file header for the reused `CollapsibleSidebar`
 * gap, the two still-inlined gaps, the enum-owned vocabulary, the `@app-md` port, and the
 * two structural leaves.
 *
 * @param props - {@link SettingsSidebarNavProps}
 */
const SettingsSidebarNav = ({
    groups,
    activeHref,
    onNavigate,
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    mobileNavAriaLabel,
}: SettingsSidebarNavProps) => {
    // Mobile leaf flattens every group into one scroll strip ΓÇö grouping only matters to the
    // desktop rail's dividers, the mobile bar has no room to spare on a section caption.
    const flatItems = groups.flatMap((group) => group.items)

    return (
        <div>
            {/* ΓöÇΓöÇ Desktop rail ΓÇö hidden below @app-md; wraps the reused `CollapsibleSidebar`
                (chrome) with this block's own rows/dividers (domain content). */}
            <div className="hidden shrink-0 @app-md:sticky @app-md:top-16 @app-md:block @app-md:h-[calc(100dvh-4rem)]">
                <CollapsibleSidebar
                    title={title}
                    collapseLabel={collapseLabel}
                    expandLabel={expandLabel}
                    storageKey={storageKey}
                >
                    {groups.map((group, index) => (
                        <React.Fragment key={group.key}>
                            {/* Divider above every group but the first ΓÇö the inlined
                                `SidebarNavGroup` gap (see file header). Spacing between it
                                and its neighbours is owned by `CollapsibleSidebar`'s own
                                `StackV gap={4}`, not a margin on this Divider. */}
                            {index > 0 ? <Divider /> : null}
                            <StackV
                                gap={1}

                                items={group.items.map((item) => () => (
                                    <DesktopNavRow
                                        item={item}
                                        isActive={item.href === activeHref}
                                        onNavigate={onNavigate}

                                    />
                                ))}
                            />
                        </React.Fragment>
                    ))}
                </CollapsibleSidebar>
            </div>

            {/* ΓöÇΓöÇ Mobile pill bar ΓÇö the OTHER leaf: chip-shaped buttons in a horizontal
                scroll strip, not the rail's row shape. Visible only below @app-md. */}
            <nav aria-label={mobileNavAriaLabel ?? title} className="sticky top-16 z-30 @app-md:hidden">
                <div className="overflow-x-auto border-b border-default bg-background/80 backdrop-blur-xl">
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        padding={{ x: 4, y: 3 }}
                        items={flatItems.map((item) => () => {
                            const isActive = item.href === activeHref
                            const Icon = DESTINATION_ICON[item.key]
                            return (
                                <button
                                    type="button"
                                    aria-current={isActive ? "page" : undefined}
                                    onClick={() => onNavigate(item.href)}
                                    className={cn(
                                        "shrink-0 rounded-full border px-3 py-2 transition-colors",
                                        isActive ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                    )}
                                >
                                    <StackH
                                        principle="icon-text"
                                        explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                        items={[
                                            () => <Icon aria-hidden focusable="false" className="size-4 shrink-0" />,
                                            () => <Typography size="sm" text={DESTINATION_LABEL[item.key]} noWrap />,
                                        ]}
                                    />
                                </button>
                            )
                        })}
                    />
                </div>
            </nav>
        </div>
    )
}

export { SettingsSidebarNav }
